  "problems": [
    {
      "type": "中身のずれ",
      "where": "blocks/1/text の hs",
      "detail": "stdにある「鉱物資源」が消え、「外国との経済関係」が「外国との貿易」に変更されている（鉱物資源などのエネルギーの記載や資源に関するニュアンスが不十分）。",
      "fix": "「会社や産業が元気になるようにすること、外国との経済関係、鉱物資源や電気・ガスなどのエネルギーを安定してとどけることを受け持つ役所です。」などと直す。"
    },
    {
      "type": "読みやすさ",
      "where": "blocks/3/text の hs",
      "detail": "「※正確には行政機関職員定員令が定める定員で、外局の職員をふくみます。」という注記が後付けされており、中学生向けとしても少し堅い法律用語がそのまま残っている。",
      "fix": "注記を本文に自然に組み込むか、簡潔な表現に直す。"
    }
  ]
}
